	[2096]={
		encounterID=2096,
		instanceID=1002,
		order=4,
		name="Overseer Korgus",
		lore="Warden to Tol Dagor, Overseer Korgus maintains the mighty island prison. His love of Azerite is widely known, even going so far as to infuse it into his bullets and test the results on his prisoners.",
		dungeonEncounterID=2104,
		uiMapID=980,
		pin={x=0.4027,y=0.6846},
		difficultyIDs={1,2,8,23},
		npcIDs={127503},
		displayIDs={81505},
		loot={
			{itemID=159628,diffs={},faction=-1},
			{itemID=159440,diffs={},faction=-1},
			{itemID=159393,diffs={},faction=-1},
			{itemID=159129,diffs={},faction=-1},
			{itemID=159331,diffs={},faction=-1},
			{itemID=159334,diffs={},faction=-1},
			{itemID=159391,diffs={},faction=-1},
			{itemID=159414,diffs={},faction=-1},
			{itemID=159657,diffs={},faction=-1},
			{itemID=159268,diffs={},faction=-1},
			{itemID=159658,diffs={},faction=-1},
		},
		sections={
			{id=16866,title="Overview",body="Overseer Korgus attacks players with several of his gun abilities. Periodically, he will load |cFF2959D3|Hspell:256198|h[Azerite Rounds: Incendiary]|h|r and |cFF2959D3|Hspell:256199|h[Azerite Rounds: Blast]|h|r into his guns for different effects!"},
			{id=16867,title="Damage Dealers",body="$bullet;Try to not be struck by multiple applications of |cFF2959D3|Hspell:256198|h[Azerite Rounds: Incendiary]|h|r, as the burning effect will stack.\n$bullet;|cFF2959D3|Hspell:256044|h[Deadeye]|h|r inflicts high damage to the first player in a line, causing them to take additional damage from subsequent |cFF2959D3|Hspell:256044|h[Deadeye]|h|r shots.\n$bullet;Watch the prison cannons as |cFF2959D3|Hspell:263345|h[Massive Blast]|h|r is being fired to avoid being destroyed."},
			{id=16868,title="Healers",body="$bullet;Players struck with |cFF2959D3|Hspell:256201|h[Azerite Rounds: Incendiary]|h|r will suffer increasing Fire damage the more they are hit.\n$bullet;|cFF2959D3|Hspell:256044|h[Deadeye]|h|r inflicts high damage to the first player in a line, causing them to take additional damage from subsequent |cFF2959D3|Hspell:256044|h[Deadeye]|h|r shots.\n$bullet;Watch the prison cannons as |cFF2959D3|Hspell:263345|h[Massive Blast]|h|r is being fired to avoid being destroyed."},
			{id=16869,title="Tanks",body="$bullet;Try to not be struck by multiple applications of |cFF2959D3|Hspell:256198|h[Azerite Rounds: Incendiary]|h|r, as the burning effect will stack.\n$bullet;|cFF2959D3|Hspell:256044|h[Deadeye]|h|r inflicts high damage to the first player in a line, causing them to take additional damage from subsequent |cFF2959D3|Hspell:256044|h[Deadeye]|h|r shots.\n$bullet;Watch the prison cannons as |cFF2959D3|Hspell:263345|h[Massive Blast]|h|r is being fired to avoid being destroyed."},
			{id=17139,title="Section 8",difficultyIDs={2,23}},
			{id=16870,title="Load Azerite Ammunition"},
