	[2097]={
		encounterID=2097,
		instanceID=1002,
		order=1,
		name="The Sand Queen",
		lore="Little is known about the monstrosity that lives in the sands surrounding the prison. No prisoners have ever survived an escape attempt, guards only finding discarded clothing and bones.",
		dungeonEncounterID=2101,
		uiMapID=974,
		pin={x=0.5103,y=0.5187},
		difficultyIDs={1,2,8,23},
		npcIDs={127479},
		displayIDs={82983},
		loot={
			{itemID=159656,diffs={},faction=-1},
			{itemID=159332,diffs={},faction=-1},
			{itemID=160215,diffs={},faction=-1},
			{itemID=160110,diffs={},faction=-1},
			{itemID=159392,diffs={},faction=-1},
			{itemID=159668,diffs={},faction=-1},
			{itemID=159460,diffs={},faction=-1},
		},
		sections={
			{id=16871,title="Overview",body="The Sand Queen creates |cFF2959D3|Hspell:257119|h[Sand Traps]|h|r around her enemies to isolate and incapacitate her prey. She also dives beneath the sands with |cFF2959D3|Hspell:257617|h[Upheaval]|h|r and springs up underneath victims."},
			{id=16872,title="Damage Dealers",body="$bullet;Avoid running into |cFF2959D3|Hspell:257119|h[Sand Trap]|h|r as they can litter the field.\n$bullet;|cFF2959D3|Hspell:257617|h[Upheaval]|h|r inflicts high damage in an area around The Sand Queen's target."},
			{id=18619,title="Healers",body="$bullet;Beware of high incoming damage when The Sand Queen uses |cFF2959D3|Hspell:257609|h[Enrage]|h|r!\n$bullet;Avoid running into |cFF2959D3|Hspell:257119|h[Sand Trap]|h|r as they can litter the field.",difficultyIDs={1}},
			{id=16873,title="Healers",body="$bullet;Beware of high incoming damage when The Sand Queen gains |cFF2959D3|Hspell:259975|h[Enrage]|h|r!\n$bullet;Avoid running into |cFF2959D3|Hspell:257119|h[Sand Trap]|h|r as they can litter the field.",difficultyIDs={2,23}},
			{id=18620,title="Tanks",body="$bullet;Avoid running into |cFF2959D3|Hspell:257119|h[Sand Trap]|h|r as they can litter the field.\n$bullet;Beware of high incoming damage when The Sand Queen uses |cFF2959D3|Hspell:257609|h[Enrage]|h|r!",difficultyIDs={1}},
			{id=16874,title="Tanks",body="$bullet;Avoid running into |cFF2959D3|Hspell:257119|h[Sand Trap]|h|r as they can litter the field.\n$bullet;Beware of high incoming damage when The Sand Queen gains |cFF2959D3|Hspell:259975|h[Enrage]|h|r!",difficultyIDs={2,23}},
			{id=17487,title="Call of the Sand Queen",body="Each of the Sand Queen's abillities call forth a Buzzing Drone to assist her.",difficultyIDs={2,23}},
			{id=17489,title="Ability",difficultyIDs={1}},
			{id=16875,title="Ability",difficultyIDs={2,23}},
			{id=17121,title="Section 6"},
			{id=17122,title="Section 7"},
			{id=17480,title="Buzzing Drone",body="If a Buzzing Drone dies nearby The Sand Queen, she gains a stack of Enrage.",difficultyIDs={2,23}},
			{id=17491,title="Section 13"},
			{id=17481,title="Section 10"},
			{id=17488,title="Section 11",difficultyIDs={1}},
		},
	},
	[2098]={
		encounterID=2098,
		instanceID=1002,
		order=2,
		name="Jes Howlis",
		lore="A vicious pirate of dubious loyalty, Jes Howlis was captured alongside his brother and locked away. After being released in a prison riot, Jes has since taken over as the de facto leader of the gang that controls the prison's lower levels.",
		dungeonEncounterID=2102,
		uiMapID=977,
		pin={x=0.3736,y=0.6846},
		difficultyIDs={1,2,8,23},
		npcIDs={127484},
		displayIDs={81739},
		loot={
			{itemID=159266,diffs={},faction=-1},
			{itemID=159306,diffs={},faction=-1},
			{itemID=159666,diffs={},faction=-1},
			{itemID=159363,diffs={},faction=-1},
			{itemID=159131,diffs={},faction=-1},
			{itemID=159293,diffs={},faction=-1},
			{itemID=159627,diffs={},faction=-1},
			{itemID=168145,diffs={1},faction=-1},
		},
		sections={
			{id=16876,title="Overview",body="Jes Howlis seeks to crush his enemies and maintain leadership through |cFF2959D3|Hspell:257785|h[Flashing Daggers]|h|r and |cFF2959D3|Hspell:257791|h[Howling Fear]|h|r.\n\nAt 70% health remaining, he uses |cFF2959D3|Hspell:257793|h[Smoke Powder]|h|r to distract them as he releases more fellow prisoners from their cells."},
			{id=16877,title="Damage Dealers",body="$bullet;Get behind a pillar when |cFF2959D3|Hspell:257785|h[Flashing Daggers]|h|r is cast to prevent taking large damage.\n$bullet;Interrupt |cFF2959D3|Hspell:257791|h[Howling Fear]|h|r when it is being cast."},
			{id=16878,title="Healers",body="$bullet;Get behind a pillar when |cFF2959D3|Hspell:257785|h[Flashing Daggers]|h|r is cast to prevent taking large damage.\n$bullet;Watch out for prisoners with stacks of |cFF2959D3|Hspell:257956|h[Motivated]|h|r as they will be inflicting high damage."},
			{id=16879,title="Tanks",body="$bullet;Get behind a pillar when |cFF2959D3|Hspell:257785|h[Flashing Daggers]|h|r is cast to prevent taking large damage.\n$bullet;Gain threat on released prisoners after |cFF2959D3|Hspell:257793|h[Smoke Powder]|h|r wears off."},
			{id=16880,title="Ability"},
			{id=17124,title="Section 6"},
			{id=17125,title="Section 7"},
			{id=17126,title="Section 8"},
			{id=17127,title="Irontide Raider",body="A released convict that will do anything to escape."},
			{id=17128,title="Bobby Howlis",difficultyIDs={2,23}},
