			{id=17493,title="Section 15"},
			{id=17496,title="Section 16"},
			{id=17131,title="Section 13"},
			{id=17132,title="Section 14"},
		},
	},
	[2099]={
		encounterID=2099,
		instanceID=1002,
		order=3,
		name="Knight Captain Valyri",
		lore="Knight Captain Valyri oversees the explosive munitions within Ashvane's armory. Unfortunately for her subordinates, her obsession with fire often creates hazardous working conditions.",
		dungeonEncounterID=2103,
		uiMapID=979,
		pin={x=0.5206,y=0.8692},
