	[2116]={
		encounterID=2116,
		instanceID=1012,
		order=4,
		name="Mogul Razdunk",
		lore="Never able to ascend to Trade Prince, Mogul Razdunk is certain that becoming the world's foremost Azerite baron will bring him fame and fortune beyond his station.",
		dungeonEncounterID=2108,
		uiMapID=1010,
		pin={x=0.6895,y=0.3773},
		difficultyIDs={1,2,8,23},
		npcIDs={132713},
		displayIDs={81816},
		loot={
