			{itemID=159455,diffs={1,2,23},faction=-1},
			{itemID=159398,diffs={1,2,23},faction=-1},
			{itemID=239024,diffs={24},faction=-1},
			{itemID=239023,diffs={24},faction=-1},
			{itemID=239025,diffs={24},faction=-1},
			{itemID=239026,diffs={24},faction=-1},
			{itemID=239027,diffs={24},faction=-1},
			{itemID=239028,diffs={24},faction=-1},
