			{id=17816,title="Section 5",difficultyIDs={2,8,23}},
			{id=18334,title="Gripping Terror",body="Destroying these tentacles allows the Kul Tiran Engineer to repair the broken artillery that is scattered throughout the wreckage.",difficultyIDs={2,8,23}},
			{id=18340,title="Demolishing Terror",body="Guard the wreckage surrounding Viq'Goth.",difficultyIDs={2,8,23}},
