			{id=17833,title="Healers",body="$bullet; |cFF2959D3|Hspell:261088|h[Hurricane Crash]|h|r inflicts lethal damage to all targets caught in the center.\n$bullet; |cFF2959D3|Hspell:260908|h[Storm Wing]|h|r inflicts significant damage to all party members."},
			{id=17834,title="Tanks",body="$bullet; Protect allies from Ji'arak Broodling summoned by |cFF2959D3|Hspell:261467|h[Matriarch's Call]|h|r.\n$bullet; |cFF2959D3|Hspell:261088|h[Hurricane Crash]|h|r inflicts lethal damage to all targets caught in the center."},
			{id=17835,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:261088|h[Hurricane Crash]|h|r inflicts lethal damage to all targets caught in the center.\n$bullet; |cFF2959D3|Hspell:261509|h[Clutch]|h|r can be interrupted by crowd control effects."},
			{id=17836,title="Section 5"},
			{id=17837,title="Section 6"},
			{id=17839,title="Ji'arak Broodling",body="Summoned by Matriarch's Call."},
