	[2144]={
		encounterID=2144,
		instanceID=1030,
		order=3,
		name="Galvazzt",
		lore="With the corruption of her temple, Sethraliss' command of lightning has created twisted elementals that roam the sunken chambers. Formed by this aberrant energy, Galvazzt seeks to grow in power by any means.",
		dungeonEncounterID=2126,
		uiMapID=1038,
		pin={x=0.4511,y=0.3012},
		difficultyIDs={1,2,8,23,24},
		npcIDs={133389,136338,175363},
		displayIDs={81654},
		loot={
			{itemID=159247,diffs={},faction=-1},
			{itemID=159442,diffs={},faction=-1},
			{itemID=158374,diffs={},faction=-1},
			{itemID=158366,diffs={},faction=-1},
			{itemID=158369,diffs={},faction=-1},
			{itemID=159664,diffs={},faction=-1},
			{itemID=168154,diffs={1,101,24},faction=-1},
		},
		sections={
			{id=17849,title="Overview",body="Galvazzt attempts to accumulate energy with |cFF2959D3|Hspell:1291598|h[Lightning Spires]|h|r. Players standing between Galvazzt and these spires become |cFF2959D3|Hspell:266923|h[Galvanized]|h|r, preventing energy from flowing to Galvazzt."},
			{id=17850,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:1291598|h[Lightning Spires]|h|r form at targeted locations, inflicting damage and knocking away any players struck.\n$bullet;Standing between Galvazzt and his |cFF2959D3|Hspell:1291598|h[Lightning Spires]|h|r prevents Galvazzt from unleashing |cFF2959D3|Hspell:266512|h[Consume Charge]|h|r."},
			{id=17851,title="Healers",body="$bullet;Standing between Galvazzt and his |cFF2959D3|Hspell:1291598|h[Lightning Spires]|h|r prevents Galvazzt from unleashing |cFF2959D3|Hspell:266512|h[Consume Charge]|h|r.\n$bullet;|cFF2959D3|Hspell:266923|h[Galvanized]|h|r inflicts significant damage to players."},
			{id=17852,title="Tanks",body="$bullet; |cFF2959D3|Hspell:1291598|h[Lightning Spires]|h|r form at targeted locations, inflicting damage and knocking away any players struck.\n$bullet;|cFF2959D3|Hspell:266923|h[Galvanized]|h|r significantly increases Physical damage taken."},
			{id=18921,body="$[!8,23\n\nOn Mythic difficulty, Galvazzt creates multiple |cFF2959D3|Hspell:1291618|h[Lightning Spires]|h|r.\n$]"},
			{id=18035,title="Section 7"},
			{id=18196,title="Section 10"},
			{id=18197,title="Section 11"},
			{id=18195,title="266923"},
			{id=18036,title="Section 8"},
			{id=35658,title="Section 15"},
		},
	},
	[2145]={
