	[2155]={
		encounterID=2155,
		instanceID=1036,
		order=3,
		name="Lord Stormsong",
		lore="Master of House Stormsong, Lord Stormsong leads the tidesages in their oceanic blessings and ways. However, not all is as it seems...",
		dungeonEncounterID=2132,
		uiMapID=1040,
		pin={x=0.4024,y=0.5373},
		difficultyIDs={1,2,8,23,24},
