			{itemID=159241,diffs={1,2,23},faction=-1},
			{itemID=159253,diffs={},faction=-1},
			{itemID=159432,diffs={1,2,23},faction=-1},
			{itemID=159446,diffs={1,2,23},faction=-1},
			{itemID=159267,diffs={1,2,23},faction=-1},
			{itemID=159385,diffs={1,2,23},faction=-1},
