	[2168]={
		encounterID=2168,
		instanceID=1031,
		order=1,
		name="Taloc",
		lore="The titan keepers enacted countless systems to detect and contain any breach from the facility. Their most powerful construct, Taloc, kept watch for any signs of corruption in the region and ruthlessly excised any that he found. But as thousands of years passed, its internal defenses began to decay, making it vulnerable to corruption.",
		dungeonEncounterID=2144,
		uiMapID=1148,
		pin={x=0.5248,y=0.3004},
		difficultyIDs={14,15,16,17},
		npcIDs={122276},
		displayIDs={33006,84871,85386},
		loot={
