	[2171]={
		encounterID=2171,
		instanceID=1041,
		order=2,
		name="Mchimba the Embalmer",
		lore="There was once a caste of Zandalari whose purpose was to preserve and defend the remains of past rulers. But when a terrible plague of corrupted blood tore through the empire, it was too risky for mortals to handle the dead. Golems were summoned for the grim work of preservation and burial; they have been used ever since.",
		dungeonEncounterID=2142,
		uiMapID=1004,
		pin={x=0.5452,y=0.2407},
		difficultyIDs={2,8,23,24},
		npcIDs={134993},
		displayIDs={83529},
		loot={
			{itemID=159618,diffs={2,23,24},faction=-1},
			{itemID=159459,diffs={2,23,24},faction=-1},
			{itemID=159667,diffs={2,23,24},faction=-1},
			{itemID=160213,diffs={2,23,24},faction=-1},
			{itemID=159312,diffs={2,23,24},faction=-1},
			{itemID=159642,diffs={2,23,24},faction=-1},
			{itemID=159409,diffs={2,23,24},faction=-1},
		},
		sections={
			{id=18136,title="Overview",body="Mchimba the Embalmer prepares his victims for mummification. |cFF2959D3|Hspell:267618|h[Drain Fluids]|h|r inflicts Nature damage over time on target player that ends in |cFF2959D3|Hspell:267626|h[Desiccation]|h|r. |cFF2959D3|Hspell:267702|h[Entomb]|h|r seals a player inside one of the chamber's crypts, after which Mchimba begins to |cFF2959D3|Hspell:271290|h[Open Coffin]|h|r on the remaining crypts one at a time, releasing a Finished Mummy from every unoccupied crypt."},
			{id=18137,title="Tank",body="$bullet;|cFF2959D3|Hspell:267702|h[Entomb]|h|r seals the afflicted player inside one of the crypts.\n$bullet;|cFF2959D3|Hspell:271290|h[Open Coffin]|h|r opens one of the crypts and summons a Finished Mummy."},
			{id=18138,title="Healer",body="$bullet;|cFF2959D3|Hspell:267618|h[Drain Fluids]|h|r inflicts Nature damage over time to the afflicted player. When the effect completes, it applies |cFF2959D3|Hspell:267626|h[Desiccation]|h|r, reducing the afflicted player's damage done and movement speed until they are healed above 90% health.\n$bullet;|cFF2959D3|Hspell:267639|h[Burn Corruption]|h|r inflicts Fire damage to target player and creates a patch of |cFF2959D3|Hspell:267874|h[Burning Ground]|h|r.\n$bullet;|cFF2959D3|Hspell:267702|h[Entomb]|h|r seals the afflicted player inside one of the crypts."},
			{id=18139,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:267702|h[Entomb]|h|r seals the afflicted player inside one of the crypts.\n$bullet;|cFF2959D3|Hspell:267618|h[Drain Fluids]|h|r inflicts Nature damage over time to the afflicted player. When the effect completes, it applies |cFF2959D3|Hspell:267626|h[Desiccation]|h|r, reducing the afflicted player's damage done and movement speed until they are healed above 90% health.\n$bullet;|cFF2959D3|Hspell:267639|h[Burn Corruption]|h|r inflicts Fire damage to target player and creates a patch of |cFF2959D3|Hspell:267874|h[Burning Ground]|h|r."},
			{id=37188,title="Section 19",difficultyIDs={2,23,24}},
			{id=37189,title="Interment Construct",difficultyIDs={2,23,24}},
			{id=37190,title="Section 21",difficultyIDs={2,23,24}},
			{id=37164,title="Section 15",difficultyIDs={2,23,24}},
			{id=37165,title="Half-Finished Mummy",difficultyIDs={2,23,24}},
			{id=37166,title="Section 11",difficultyIDs={2,23,24}},
			{id=18140,title="Section 5",difficultyIDs={2,23,24}},
			{id=18148,title="Section 13",difficultyIDs={2,23,24}},
			{id=18141,title="Section 6",difficultyIDs={2,23,24}},
			{id=37168,title="Section 18",difficultyIDs={2,23,24}},
			{id=18142,title="Section 7",difficultyIDs={2,23,24}},
			{id=18143,title="Section 8",difficultyIDs={2,23,24}},
			{id=18147,title="Section 12",difficultyIDs={2,23,24}},
			{id=18144,title="Struggle",body="While trapped, players can struggle against the doors of the crypt, alerting other players to their presence.",difficultyIDs={2,23,24}},
			{id=18145,title="Finished Mummy",body="When a coffin that does not contain a player is opened, a Finished Mummy will emerge and attack the party.",difficultyIDs={2,23,24}},
			{id=18146,title="Section 11",difficultyIDs={2,23,24}},
			{id=18862,title="Heroic and Mythic Difficulty Only",body="Kings' Rest is not available in Normal Difficulty.",difficultyIDs={1}},
		},
