	[2172]={
		encounterID=2172,
		instanceID=1041,
		order=4,
		name="Dazar, The First King",
		lore="Dazar. The founder and first King of Zandalar, who led an exodus of his people out of the muck and mire and built a city of gold. The first tamer of raptors. The warrior undefeated. The father of a kingdom.\n\nHis eternal repose cut short by Zul's dark magic, it lies to you to once again put him to rest.",
		dungeonEncounterID=2143,
		uiMapID=1004,
		pin={x=0.1386,y=0.4822},
		difficultyIDs={2,8,23,24},
