	[2173]={
		encounterID=2173,
		instanceID=1023,
		order=2,
		name="Dread Captain Lockwood",
		lore="Dread Captain Lockwood commands a host of Azerite artillery. Currently her cannons are trained on the palace, threatening to reduce the seat of the Proudmoore's power to rubble unless they surrender.",
		dungeonEncounterID=2109,
		uiMapID=1162,
		pin={x=0.5476,y=0.6025},
		difficultyIDs={1,2,8,23},
		npcIDs={129208},
		displayIDs={88579},
		loot={
			{itemID=159309,diffs={2,8,23},faction=-1},
			{itemID=159379,diffs={2,8,23},faction=-1},
			{itemID=159623,diffs={2,8,23},faction=-1},
			{itemID=159237,diffs={2,8,23},faction=-1},
			{itemID=159429,diffs={2,8,23},faction=-1},
			{itemID=159434,diffs={2,8,23},faction=-1},
			{itemID=159372,diffs={2,8,23},faction=-1},
			{itemID=159250,diffs={2,8,23},faction=-1},
			{itemID=159320,diffs={2,8,23},faction=-1},
			{itemID=159649,diffs={2,8,23},faction=-1},
		},
		sections={
			{id=18221,title="Overview",body="Dread Captain Lockwood continually retreats from players using |cFF2959D3|Hspell:272471|h[Evasive]|h|r and assaults them with |cFF2959D3|Hspell:273470|h[Gut Shot]|h|r.\n\nUpon reaching 66% and 33% health, Dread Captain Lockwood |cFF2959D3|Hspell:268752|h[Withdraws]|h|r to her ship and her crew assaults the party while the area is constantly bombarded by |cFF2959D3|Hspell:268443|h[Dread Volley]|h|r.\n\n|cFF2959D3|Hspell:268976|h[Unstable Ordnance]|h|r must be used to bombard Captain Lockwood's ship and return her to the battlefield."},
			{id=18222,title="Damage Dealers",body="$bullet;Pickup |cFF2959D3|Hspell:268976|h[Unstable Ordnance]|h|r and use it to damage the ship.\n$bullet;|cFF2959D3|Hspell:463182|h[Fiery Ricochet]|h|r bounces to 2 additional players and inflicts additional Fire damage."},
			{id=18223,title="Healers",body="$bullet;|cFF2959D3|Hspell:463182|h[Fiery Ricochet]|h|r bounces to 2 additional players and inflicts additional Fire damage.\n$bullet;|cFF2959D3|Hspell:273470|h[Gut Shot]|h|r continually damages random party members."},
			{id=18224,title="Tanks",body="$bullet;Face Ashvane Deckhand's |cFF2959D3|Hspell:268230|h[Crimson Swipe]|h|r away from the party.\n$bullet;Avoid |cFF2959D3|Hspell:269029|h[Clear the Deck]|h|r."},
			{id=30256,title="Section 18",difficultyIDs={8,23}},
			{id=30258,title="Section 19",difficultyIDs={8,23}},
			{id=30257,title="Section 17"},
			{id=18915,title="Section 16",difficultyIDs={2,8,23}},
