	},
	[2199]={
		encounterID=2199,
		instanceID=1028,
		order=10,
		name="Azurethos, The Winged Typhoon",
		lore="Azurethos, the terror of the Kul'tiran seas, marshalls the power of wind to force enemies out of its roost, cause waterspouts, and capsize ships. He has earned his reputation as one of the deadliest beasts in Kul Tiras.",
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={136385},
		displayIDs={58717},
		loot={
			{itemID=161360,diffs={14},faction=-1},
