	[2329]={
		encounterID=2329,
		instanceID=1028,
		order=4,
		name="Ivus the Forest Lord",
		lore="Summoned by the night elves in times of desperation, Ivus the Forest Lord has wielded his raw strength against the Horde time and again. Now he has returned from Alterac Valley to stand in defense of his home and crush any who threaten it.",
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={144946},
		displayIDs={88956},
		loot={
			{itemID=166689,diffs={14},faction=-3},
			{itemID=166692,diffs={14},faction=-3},
			{itemID=166697,diffs={14},faction=-3},
