	[2331]={
		encounterID=2331,
		instanceID=1178,
		order=8,
		name="King Mechagon",
		lore="As maniacal as he is brilliant, King Mechagon despises all organic life. With his mechoriginator primed and ready, nothing stands in the way of his scheme to purge the curse of flesh from Azeroth and mechanize the entire world.",
