			{id=19567,title="Section 33",difficultyIDs={16}},
			{id=19568,title="Section 34",difficultyIDs={16}},
			{id=19095,title="Section 9",body="Mekkatorque periodically calls in Spark Bot units to seek out his enemies.\n$[!15\n\nIn Heroic difficulty, Hyperdrive causes Mekkatorque to deploy an additional Spark Bot.$]$[!16\n\nIn Mythic difficulty, Hyperdrive causes Mekkatorque to deploy an additional Spark Bot.$]"},
			{id=19096,title="Spark Bot",body="Players affected by |cFF2959D3|Hspell:284168|h[Shrunken]|h|r can tamper with Spark Bots and shut them down from within."},
			{id=19734,title="Section 12",difficultyIDs={14,15,17}},
			{id=19836,title="Section 75",difficultyIDs={16}},
			{id=19454,title="Section 30",body="$[!17 \n\nIn Raid Finder difficulty, shutdown codes are visible to all players.$]$[!15\n\nIn Heroic difficulty, shutdown codes are only visible to players in other Spark Bots.$]$[!16\n\nIn Mythic difficulty, shutdown codes are only visible to players in other Spark Bots.$]"},
