	[2336]={
		encounterID=2336,
		instanceID=1178,
		order=5,
		name="Tussle Tonks",
		lore="Mechagon's premier mechgineers test their mettle (and metal) by building customized combat robots. While these tonks typically battle each other for glory, they combine their efforts to repel foolhardy organic intruders who dare venture into Mechagon.",
		dungeonEncounterID=2257,
		uiMapID=1491,
		pin={x=0.2801,y=0.7078},
		difficultyIDs={2,8,23},
		npcIDs={144244,145185},
		displayIDs={91216,91879},
		loot={
			{itemID=168958,diffs={},faction=-1},
			{itemID=168965,diffs={},faction=-1},
			{itemID=168964,diffs={},faction=-1},
			{itemID=168962,diffs={},faction=-1},
