	[2337]={
		encounterID=2337,
		instanceID=1176,
		order=8,
		name="Stormwall Blockade",
		lore="Brother Joseph and Sister Katherine are devout worshippers of the waves. These proud Kul Tirans would gladly risk their lives to ensure the safety of their compatriots. Their command over sea and storm is awesome to behold, as are the ancient and powerful rituals they practice.",
		dungeonEncounterID=2280,
		uiMapID=1352,
		pin={x=0.4931,y=0.9416},
		difficultyIDs={14,15,16,17},
		npcIDs={146251,146253,146256},
		displayIDs={89304,89306,90322},
		loot={
			{itemID=165819,diffs={},faction=-1},
			{itemID=165506,diffs={},faction=-1},
			{itemID=165601,diffs={},faction=-1},
			{itemID=165923,diffs={},faction=-1},
			{itemID=165528,diffs={},faction=-1},
			{itemID=165557,diffs={},faction=-1},
			{itemID=165603,diffs={},faction=-1},
			{itemID=165556,diffs={},faction=-1},
			{itemID=165546,diffs={},faction=-1},
			{itemID=165602,diffs={},faction=-1},
			{itemID=165590,diffs={},faction=-1},
			{itemID=165585,diffs={},faction=-1},
			{itemID=165822,diffs={},faction=-1},
		},
		sections={
			{id=19252,title="Overview",body="Working to cover the main portion of the Alliance fleet as they fell back, a cadre of Stormsong tidepriests have established a blockade and summoned an overwhelming elemental to wash away Dazar'alor's port area. Re-establish a foothold on the docks, overrun the alliance ships and return the summoned monstrosity back to the deep before they destroy a large portion of the city."},
			{id=19253,title="Tanks",body="$bullet; Interrupt Brother Joseph's and Sister Katherine's Empowerments when you can.\n$bullet; Use |cFF2959D3|Hspell:285000|h[Kelp-Wrapped Fists]|h|r to slow Energizing Storms."},
			{id=19254,title="Healers",body="$bullet; If affected by |cFF2959D3|Hspell:284405|h[Tempting Song]|h|r, try to position yourself as far away from the Siren as possible.\n$bullet; Keep moving to avoid being hit by |cFF2959D3|Hspell:284262|h[Voltaic Flash]|h|r."},
			{id=19255,title="Damage Dealers",body="$bullet; If affected by |cFF2959D3|Hspell:284405|h[Tempting Song]|h|r, try to position yourself as far away from the Siren as possible.\n$bullet; Keep moving to avoid being hit by |cFF2959D3|Hspell:284262|h[Voltaic Flash]|h|r.\n$bullet; Use |cFF2959D3|Hspell:285350|h[Storm's Wail]|h|r to remove |cFF2959D3|Hspell:285075|h[Freezing Tidepools]|h|r."},
			{id=19425,title="Empowering the storm",body="Throughout the course of the fight, Laminaria receives energy from various sources. When Laminaria reaches 100 Energy, |cFF2959D3|Hspell:284760|h[Catastrophic Tides]|h|r is cast."},
			{id=19322,title="Section 43"},
			{id=19257,title="Stage One: Storm the Ships"},
			{id=19261,title="Sister Katherine"},
			{id=19273,title="Section 13"},
			{id=19274,title="Section 14"},
			{id=19275,title="Section 15"},
			{id=19427,title="Section 46",body="${\n\nAfter casting |cFF2959D3|Hspell:287995|h[Electric Shroud]|h|r, each tidepriest will cast |cFF2959D3|Hspell:284765|h[Tidal Empowerment]|h|r."},
			{id=19271,title="Section 16"},
			{id=19428,title="Section 18"},
			{id=19320,title="Soul of the Tidepriestess",body="When Sister Katherine dies, her soul appears and begins channeling |cFF2959D3|Hspell:287889|h[Greater Storm's Empowerment]|h|r on Laminaria. When both Tidepriests are dead, their souls depart."},
			{id=19321,title="Section 42"},
			{id=19262,title="Brother Joseph"},
			{id=19277,title="Section 19"},
			{id=19278,title="Section 20"},
			{id=19279,title="Tempting Siren"},
			{id=19317,title="Section 38"},
			{id=19537,title="Section 46",body="${\n\nAfter casting |cFF2959D3|Hspell:286558|h[Tidal Shroud]|h|r, each tidepriest will cast |cFF2959D3|Hspell:287887|h[Storm's Empowerment]|h|r."},
			{id=19538,title="Section 16"},
			{id=19539,title="Section 18"},
			{id=19540,title="Soul of the Tidepriest",body="When Brother Joseph dies, his soul appears and begins channeling |cFF2959D3|Hspell:284864|h[Greater Tidal Empowerment]|h|r on Laminaria. When both Tidepriests are dead, their souls depart."},
			{id=19541,title="Section 42"},
			{id=19623,title="Section 17",body="${\n\nThe tidepriests cast |cFF2959D3|Hspell:284393|h[Translocate]|h|r when they reach certain health thresholds.",difficultyIDs={15,16}},
			{id=19621,title="Spawn of Laminaria",body="When the Spawn of Laminaria appears, it casts |cFF2959D3|Hspell:288258|h[Sea Swell]|h|r.",difficultyIDs={16}},
			{id=19622,title="Section 51",difficultyIDs={16}},
			{id=19319,title="Translocation Pedestal",body="Teleports the user to the other ship. If both Brother Joseph and Sister Katherine are dead, the user is teleported back to the docks instead."},
			{id=19258,title="Stage Two: Laminaria"},
			{id=19719,title="Souls of the Deep",body="The souls of Brother Joseph and Sister Katherine aid Laminaria in his assault on Dazar'alor.",difficultyIDs={16}},
			{id=19433,title="Section 49"},
			{id=19542,title="Section 40"},
			{id=19309,title="Section 30"},
			{id=19735,title="Section 37",difficultyIDs={14,15,17}},
			{id=19316,title="Section 37",body="${\n$[!16\nOn Mythic Difficulty, Freezing Tidepools clear a stack of |cFF2959D3|Hspell:285382|h[Kelp Wrapping]|h|r every second on any Energized Storm within its boundaries.$]",difficultyIDs={16}},
			{id=19310,title="Section 31",body="${\n$[!16\n\nOn Mythic Difficulty, |cFF2959D3|Hspell:285017|h[Ire of the Deep]|h|r also knocks back all players away, with the knock back force divided among all players struck.$]"},
			{id=19543,title="Section 32",difficultyIDs={14,17}},
			{id=19544,title="Energized Storm",body="Upon spawning, Energized Storms move towards Laminaria. When they reach their destination, they cast |cFF2959D3|Hspell:285342|h[Energizing Wake]|h|r.\n\nOn Normal and LFR Difficulties When an Energized Storm dies, it casts |cFF2959D3|Hspell:285350|h[Storm's Wail]|h|r on a random player.",difficultyIDs={14,17}},
			{id=19545,title="Section 34",difficultyIDs={14,17}},
			{id=19546,title="Section 32",difficultyIDs={15}},
			{id=19547,title="Energized Storm",body="Upon spawning, Energized Storms move towards Laminaria. When they reach their destination, they cast |cFF2959D3|Hspell:285342|h[Energizing Wake]|h|r.\n\nOn Heroic and Mythic Difficulties, when an Energized Storm dies, it leaves behind a Energized Remnant.",difficultyIDs={15}},
			{id=19548,title="Section 34",difficultyIDs={15}},
			{id=19549,title="Energized Remnant",body="Energized Remnant continuously casts |cFF2959D3|Hspell:285420|h[Unbound Energy]|h|r until it is picked up by a player. Picking up an Energized Remnant applies |cFF2959D3|Hspell:285350|h[Storm's Wail]|h|r.",difficultyIDs={15}},
			{id=19550,title="Section 36",difficultyIDs={15}},
			{id=19311,title="Section 32",difficultyIDs={16}},
			{id=19312,title="Energized Storm",body="Upon spawning, Energized Storms move towards Laminaria. When they reach their destination, they cast |cFF2959D3|Hspell:285342|h[Energizing Wake]|h|r.\n\nOn Heroic and Mythic difficulties, when an Energized Storm dies, it leaves behind a Energized Remnant.",difficultyIDs={16}},
			{id=19313,title="Section 34",difficultyIDs={16}},
			{id=19314,title="Energized Remnant",body="Energized Remnant continuously casts |cFF2959D3|Hspell:285420|h[Unbound Energy]|h|r until it is picked up by a player. Picking up an Energized Remnant applies |cFF2959D3|Hspell:285350|h[Storm's Wail]|h|r.",difficultyIDs={16}},
			{id=19315,title="Section 36",difficultyIDs={16}},
			{id=19838,title="Section 54"},
		},
	},
	[2339]={
		encounterID=2339,
		instanceID=1178,
		order=6,
		name="K.U.-J.0.",
		lore="As the respository for the city's refuse, the Under Junk is a prime target for gnomes from Bondo's gang who intend to steal valuable mechanical components. While Trash Mistress Wendy Cogsworth ceaselessly sorts the city's junk, her loyal guard dog, K.U.-J.0., keeps out unwelcome intruders--mechagnomes and adventurers alike.",
		dungeonEncounterID=2258,
		uiMapID=1494,
		pin={x=0.4578,y=0.387},
		difficultyIDs={2,8,23},
		npcIDs={144246},
		displayIDs={90775},
		loot={
			{itemID=168969,diffs={},faction=-1},
			{itemID=168970,diffs={},faction=-1},
			{itemID=168972,diffs={},faction=-1},
			{itemID=168971,diffs={},faction=-1},
			{itemID=168968,diffs={},faction=-1},
			{itemID=170508,diffs={},faction=-1},
			{itemID=168744,diffs={104},faction=-1},
