	[2351]={
		encounterID=2351,
		instanceID=1179,
		order=5,
		name="Orgozoa",
		lore="Orgozoa tends to Azshara's hatchery, preparing for the day her incubating horrors are unleashed upon Azeroth.",
		dungeonEncounterID=2303,
		uiMapID=1517,
		pin={x=0.7496,y=0.4749},
