	[2352]={
		encounterID=2352,
		instanceID=1179,
		order=1,
		name="Abyssal Commander Sivara",
		lore="A master of both martial and magical arts, Abyssal Commander Sivara has ruthlessly led Azshara's vanguard to countless victories.",
		dungeonEncounterID=2298,
		uiMapID=1512,
		pin={x=0.5,y=0.484},
		difficultyIDs={14,15,16,17},
		npcIDs={153134},
		displayIDs={91072},
		loot={
			{itemID=168359,diffs={},faction=-1},
			{itemID=168273,diffs={},faction=-1},
			{itemID=168361,diffs={},faction=-1},
			{itemID=168345,diffs={},faction=-1},
			{itemID=168901,diffs={},faction=-1},
			{itemID=168903,diffs={},faction=-1},
			{itemID=168276,diffs={},faction=-1},
			{itemID=168386,diffs={},faction=-1},
			{itemID=168477,diffs={},faction=-1},
			{itemID=168387,diffs={},faction=-1},
			{itemID=168377,diffs={},faction=-1},
			{itemID=168306,diffs={},faction=-1},
			{itemID=168341,diffs={},faction=-1},
			{itemID=168390,diffs={},faction=-1},
			{itemID=168818,diffs={},faction=-1},
			{itemID=168371,diffs={},faction=-1},
			{itemID=168384,diffs={},faction=-1},
			{itemID=168905,diffs={},faction=-1},
		},
		sections={
			{id=19995,title="Overview",body="Sivara begins her assault by marking all players with |cFF2959D3|Hspell:294711|h[Frost Mark]|h|r or |cFF2959D3|Hspell:294715|h[Toxic Brand]|h|r. These volatile compounds will cause an |cFF2959D3|Hspell:294847|h[Unstable Mixture]|h|r if a player is ever afflicted with both marks."},
			{id=19996,title="Tanks",body="$bullet;Position away from players of an opposing mark and avoid attacks of the opposing element.\n$bullet;Minimize the number of |cFF2959D3|Hspell:300701|h[Rimefrost]|h|r and |cFF2959D3|Hspell:300705|h[Septic Taint]|h|r stacks.\n$bullet;|cFF2959D3|Hspell:300701|h[Rimefrost]|h|r and |cFF2959D3|Hspell:300705|h[Septic Taint]|h|r creates |cFF2959D3|Hspell:300961|h[Frozen Ground]|h|r and |cFF2959D3|Hspell:300962|h[Septic Ground]|h|r upon expiration."},
			{id=19997,title="Healers",body="$bullet;Position away from players of an opposing mark and avoid attacks of the opposing element.\n$bullet;|cFF2959D3|Hspell:294726|h[Chimeric Marks]|h|r inflicts periodic damage to the entire raid.\n$bullet;|cFF2959D3|Hspell:294847|h[Unstable Mixture]|h|r causes high raid wide damage."},
			{id=19998,title="Damage Dealers",body="$bullet;Position away from players of an opposing mark and avoid attacks of the opposing element.\n$bullet; Intercept |cFF2959D3|Hspell:295601|h[Frostshock Bolts]|h|r that are the same element as your mark.\n$bullet; |cFF2959D3|Hspell:295346|h[Overflow]|h|r damage is evenly divided amongst all players it hits."},
			{id=19999,title="Section 5",body="${\n\n\nComing into contact with a player of an opposite mark or taking damage of the opposite element afflicts players with |cFF2959D3|Hspell:294847|h[Unstable Mixture]|h|r.\n$[!16\nOn Mythic Difficulty, Abyssal Commander Sivara continues casting Chimeric Marks, stacking |cFF2959D3|Hspell:294711|h[Frost Mark]|h|r and |cFF2959D3|Hspell:294715|h[Toxic Brand]|h|r.$]"},
			{id=20000,title="Section 6"},
			{id=20003,title="Section 18",difficultyIDs={15,16}},
			{id=20015,title="Section 20",difficultyIDs={15,16}},
			{id=20001,title="Section 7"},
			{id=20004,title="Section 19",difficultyIDs={15,16}},
			{id=20016,title="Section 21",difficultyIDs={15,16}},
			{id=20005,title="Section 8"},
			{id=20222,title="Section 22"},
			{id=20300,title="Section 22"},
			{id=20301,title="Section 23"},
			{id=20304,title="Section 26"},
			{id=20302,title="Section 24"},
			{id=20305,title="Section 27"},
			{id=20014,title="Section 19",body="${\n\nAbyssal Commander Sivara casts Overwhelming Barrage when she reaches 100 Energy."},
			{id=20006,title="Section 9"},
			{id=20007,title="Section 10"},
			{id=20306,title="Section 28"},
			{id=20008,title="Section 11"},
			{id=20307,title="Section 29"},
			{id=20009,title="Section 13",difficultyIDs={14,15,16}},
			{id=20010,title="Section 14"},
			{id=20011,title="Section 15"},
			{id=20012,title="Section 16",body="$[!15,16\n\nOn Heroic difficulty and above, |cFF2959D3|Hspell:295791|h[Inversion]|h|r also inverts all pools of |cFF2959D3|Hspell:300961|h[Frozen Ground]|h|r and |cFF2959D3|Hspell:300962|h[Septic Ground]|h|r.$]",difficultyIDs={14,15,16}},
			{id=20303,title="Section 25",difficultyIDs={14,15,16}},
		},
	},
	[2353]={
		encounterID=2353,
		instanceID=1179,
		order=3,
		name="Radiance of Azshara",
		lore="Using her handmaiden as a willing sacrifice, Azshara has forged into being an elemental of storm and magic. Powered by the soul of the devoted vassal, the resulting monstrosity is the avatar of Azshara's radiance.",
		dungeonEncounterID=2305,
		uiMapID=1513,
		pin={x=0.4711,y=0.1918},
		difficultyIDs={14,15,16,17},
		npcIDs={152364},
		displayIDs={89445},
		loot={
			{itemID=168475,diffs={},faction=-1},
			{itemID=168478,diffs={},faction=-1},
			{itemID=168355,diffs={},faction=-1},
			{itemID=169313,diffs={},faction=-1},
			{itemID=168348,diffs={},faction=-1},
			{itemID=168336,diffs={},faction=-1},
			{itemID=168360,diffs={},faction=-1},
			{itemID=168388,diffs={},faction=-1},
