		},
	},
	[2354]={
		encounterID=2354,
		instanceID=1179,
		order=4,
		name="Lady Ashvane",
		lore="Priscilla Ashvane's relentless pursuit of power has ultimately led her to the Eternal Palace and into a dark pact with Queen Azshara. But what Ashvane receives in return for her loyalty may be more than she bargained for.",
		dungeonEncounterID=2304,
		uiMapID=1513,
		pin={x=0.4772,y=0.6826},
		difficultyIDs={14,15,16,17},
		npcIDs={152236},
		displayIDs={91478},
		loot={
			{itemID=168354,diffs={},faction=-1},
			{itemID=168870,diffs={},faction=-1},
			{itemID=168877,diffs={},faction=-1},
			{itemID=168347,diffs={},faction=-1},
			{itemID=169311,diffs={},faction=-1},
