		instanceID=1178,
		order=1,
		name="King Gobbamak",
		lore="Obsessed with hoarding dangerous technology found amongst the scrap, King Gobbamak sits upon a pile of doomsday weapons that he lacks the intelligence to operate or understand.",
		dungeonEncounterID=2290,
		uiMapID=1490,
		pin={x=0.5802,y=0.2734},
