	[2358]={
		encounterID=2358,
		instanceID=1178,
		order=2,
		name="Gunker",
		lore="After years of coalescing into a concentrated cesspool, Mechagon's toxic waste has gained malevolent sentience. With the sanitation systems disabled, Gunker is free to ooze across all of Azeroth.",
		dungeonEncounterID=2292,
		uiMapID=1490,
		pin={x=0.6639,y=0.6491},
