			{id=20468,title="Section 119"},
			{id=20353,title="Azshara's Devoted"},
			{id=20354,title="Section 64"},
			{id=20483,title="Azshara's Indomitable",body="Immune to crowd-controlling effects."},
			{id=20484,title="Section 64"},
			{id=20258,title="Queen Azshara"},
			{id=20464,title="Section 31"},
			{id=20412,title="Section 29",body="$[!14\nIn Normal Difficulty, players are given one decree they must obey.$]$[!15\nIn Heroic Difficulty, players are given up to two decrees they must obey.$]$[!16\nIn Mythic Difficulty, players are given up to three decrees they must obey.$]$[!17\nIn Raid Finder Difficulty, players are given one decree they must obey.$]"},
