			{id=20419,title="Section 96",difficultyIDs={15,16}},
			{id=20340,title="Stage Three: Song of the Tides",body="Azshara calls her Tidemistresses to join the fight. Each will stand on one of the Ancient Wards and periodically drain them."},
			{id=20355,title="Loyal Myrmidon",difficultyIDs={14,15,16}},
