	[2362]={
		encounterID=2362,
		instanceID=1028,
		order=3,
		name="Ulmath, the Soulbinder",
		lore="Ulmath, the Soulbinder, seeks to enthrall the restless spirits of Nazjatar. If left unchecked, it will amass an unstoppable undead force bound to its malevolent will.",
		dungeonEncounterID=2317,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={152729,152736},
		displayIDs={90989,91569,91573},
		loot={
			{itemID=170093,diffs={},faction=-1},
			{itemID=170095,diffs={},faction=-1},
			{itemID=170090,diffs={},faction=-1},
			{itemID=169317,diffs={},faction=-1},
			{itemID=168603,diffs={},faction=-1},
