	[2373]={
		encounterID=2373,
		instanceID=1180,
		order=7,
		name="Drest'agath",
		lore="The grotesque amalgam of flesh known as Drest'agath slumbered beneath Ny'alotha for millennia until being awakened by N'Zoth's return. Now she rises like a revolting boil, ready to burst and spread her vile pestilence across Azeroth.",
		dungeonEncounterID=2343,
		uiMapID=1595,
		pin={x=0.3273,y=0.5729},
		difficultyIDs={14,15,16,17},
		npcIDs={207925,234435,234436,234437},
		displayIDs={93541,93542,93543,94583},
		loot={
			{itemID=172195,diffs={},faction=-1},
