	[2378]={
		encounterID=2378,
		instanceID=1028,
		order=1,
		name="Grand Empress Shek'zara",
		lore="With the awakening of N'Zoth, Shek'zara, empress of the mantid, pledged her swarm to the old god's will. In service of her dark master, she unleashed her forces upon the Vale of Eternal Blossoms to claim Pandaria in N'Zoth's name.",
		dungeonEncounterID=2351,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={147855,154638,155851},
		displayIDs={86376,86379,92227},
		loot={
			{itemID=174234,diffs={},faction=-1},
			{itemID=174264,diffs={},faction=-1},
			{itemID=174268,diffs={},faction=-1},
			{itemID=174255,diffs={},faction=-1},
			{itemID=174243,diffs={},faction=-1},
		},
		sections={
			{id=21114,title="Overview",body="Grand Empress Shek'zara uses her powerful voice and Zara'thik Swarmguard to overwhelm enemies."},
			{id=21115,title="Healers",body="$bullet; Seek protection inside of a |cFF2959D3|Hspell:314323|h[Sound Barrier]|h|r during |cFF2959D3|Hspell:314333|h[Force and Verve]|h|r.\n$bullet; Avoid sound waves emitted during |cFF2959D3|Hspell:314306|h[Song of the Empress]|h|r."},
			{id=21116,title="Tanks",body="$bullet; Protect allies from Mantid summoned by |cFF2959D3|Hspell:314307|h[Summon Swarmguard]|h|r.\n$bullet; Seek protection inside of a |cFF2959D3|Hspell:314323|h[Sound Barrier]|h|r during |cFF2959D3|Hspell:314333|h[Force and Verve]|h|r.\n$bullet; Avoid sound waves emitted during |cFF2959D3|Hspell:314306|h[Song of the Empress]|h|r."},
			{id=21117,title="Damage Dealers",body="$bullet; Defeat waves of Mantid summoned by |cFF2959D3|Hspell:314307|h[Summon Swarmguard]|h|r.\n$bullet; Seek protection inside of a |cFF2959D3|Hspell:314323|h[Sound Barrier]|h|r during |cFF2959D3|Hspell:314333|h[Force and Verve]|h|r.\n$bullet; Avoid sound waves emitted during |cFF2959D3|Hspell:314306|h[Song of the Empress]|h|r."},
			{id=21126,title="Section 5"},
			{id=21138,title="Section 11"},
			{id=21139,title="Section 12"},
			{id=21127,title="Section 6"},
			{id=21128,title="Zara'thik Swarmguard"},
			{id=21130,title="Section 9"},
			{id=21129,title="Zara'thik Ambershaper"},
			{id=21131,title="Section 10"},
		},
	},
	[2381]={
		encounterID=2381,
		instanceID=1028,
		order=1,
		name="Vuk'laz the Earthbreaker",
		lore="Plumbing the forgotten depths of Azeroth, Prophet Skitra unearthed a devastating aqir known as Vuk'laz the Earthbreaker. Now freed from its subterranean slumber, Vuk'laz turns its destructive power against those who oppose N'Zoth.",
		dungeonEncounterID=2353,
		pin={x=0.5,y=0.5},
		difficultyIDs={14,15,16,17},
		npcIDs={160970,207910},
		displayIDs={85193,92906},
		loot={
			{itemID=174237,diffs={},faction=-1},
			{itemID=174469,diffs={},faction=-1},
			{itemID=174250,diffs={},faction=-1},
			{itemID=174258,diffs={},faction=-1},
			{itemID=174247,diffs={},faction=-1},
		},
		sections={
			{id=21159,title="Overview",body="Vuk'laz is a living weapon of war that attempts to overcome its enemies with devastating physical attacks. As the battle rages Vuk'laz summons scarabs to its aid from beneath the |cFF2959D3|Hspell:314659|h[Writhing Sands]|h|r."},
			{id=21160,title="Damage Dealers",body="$bullet;Position carefully when Vuk'laz creates a |cFF2959D3|Hspell:314527|h[Tremor Wave]|h|r.\n$bullet;Quickly dispatch scarabs that emerge from the |cFF2959D3|Hspell:314659|h[Writhing Sands]|h|r."},
			{id=21161,title="Healers",body="$bullet;Position carefully when Vuk'laz creates a |cFF2959D3|Hspell:314527|h[Tremor Wave]|h|r.\n$bullet;|cFF2959D3|Hspell:314618|h[Crushing Claws]|h|r inflicts heavy unavoidable damage."},
			{id=21162,title="Tanks",body="$bullet;Position carefully when Vuk'laz creates a |cFF2959D3|Hspell:314527|h[Tremor Wave]|h|r.\n$bullet;|cFF2959D3|Hspell:314618|h[Crushing Claws]|h|r inflicts heavy unavoidable damage."},
			{id=21164,title="Section 6"},
			{id=21165,title="Section 6"},
			{id=21168,title="Aqir Scarab",body="Aqir Scarabs emerge from the sands to swarm and overwhelm players."},
			{id=21166,title="Section 6"},
			{id=21167,title="Section 6"},
		},
	},
	[2654]={
		encounterID=2654,
		instanceID=1023,
		order=1,
		name="Chopper Redhook",
		lore="Chopper Redhook's brutality is feared throughout Kul Tiras. Supported by Irontide forces, Chopper is free to rampage through Boralus, relishing the chaos rampant in the streets.",
		dungeonEncounterID=2098,
		uiMapID=1162,
		pin={x=0.5777,y=0.2888},
		difficultyIDs={2,8,23},
		npcIDs={128650},
		displayIDs={84821},
		loot={
			{itemID=159972,diffs={2,8,23},faction=-1},
			{itemID=159965,diffs={2,8,23},faction=-1},
			{itemID=159969,diffs={2,8,23},faction=-1},
			{itemID=159973,diffs={2,8,23},faction=-1},
			{itemID=162541,diffs={2,8,23},faction=-1},
			{itemID=159427,diffs={2,8,23},faction=-1},
			{itemID=159251,diffs={2,8,23},faction=-1},
			{itemID=159968,diffs={2,8,23},faction=-1},
		},
		sections={
			{id=30428,title="Overview",body="Chopper Redhook fixates on a random enemy. The longer Chopper chases enemies, the faster he gets with |cFF2959D3|Hspell:257649|h[Boiling Rage]|h|r.\n\nAs the fight progresses, Irontide forces engage the party while the area is bombarded by a continual |cFF2959D3|Hspell:257585|h[Cannon Barrage]|h|r.\n\n|cFF2959D3|Hspell:273716|h[Heavy Ordnance]|h|r appears during the barrage, and  unless it is detonated before time expires it will explode and damage the party."},
			{id=30429,title="Damage Dealers",body="$bullet;Kill Irontide forces.\n$bullet;When the target of |cFF2959D3|Hspell:257459|h[On the Hook]|h|r, run away."},
			{id=30430,title="Healers",body="$bullet;Irontide Powdershots inflict damage to everyone in the party.\n$bullet;If |cFF2959D3|Hspell:273716|h[Heavy Ordnance]|h|r explodes it does massive damage to the party.\n$bullet;When the target of |cFF2959D3|Hspell:257459|h[On the Hook]|h|r, run away."},
			{id=30431,title="Tanks",body="$bullet;Avoid being in melee range with Chopper Redhook due to |cFF2959D3|Hspell:256867|h[Heavy Hitter]|h|r.\n$bullet;Face Irontide Cleaver's |cFF2959D3|Hspell:257292|h[Heavy Slash]|h|r away from the party.\n$bullet;Run over |cFF2959D3|Hspell:273716|h[Heavy Ordnance]|h|r to prevent them from damaging the party."},
			{id=30432,title="Section 5",difficultyIDs={2,8,23}},
			{id=30433,title="Section 6",difficultyIDs={2,8,23}},
			{id=30434,title="Section 17",difficultyIDs={2,8,23}},
			{id=30435,title="Section 16",difficultyIDs={2}},
			{id=30436,title="Section 8",difficultyIDs={2}},
			{id=30437,title="Section 16",difficultyIDs={8,23}},
			{id=30438,title="Section 8",difficultyIDs={8,23}},
			{id=30439,title="Section 9",difficultyIDs={2,8,23}},
			{id=30440,title="Section 18",difficultyIDs={2,8,23}},
			{id=30441,title="Irontide Cleaver",body="A Irontide bruiser with a heavy melee attack.",difficultyIDs={2,8,23}},
			{id=30442,title="Section 11",difficultyIDs={2,8,23}},
			{id=30443,title="Irontide Powdershot",body="An Irontide marksman capable of inflicting damage to the party.",difficultyIDs={2,8,23}},
			{id=30444,title="Section 13",difficultyIDs={2,8,23}},
			{id=30445,title="Heroic and Mythic Difficulty Only",body="Siege of Boralus is not available in Normal difficulty.",difficultyIDs={1}},
		},
	},
